41	    if length(data_size) > 2 % Data has averages and series
42	        dims.averages   = find(data_size == header.averages);
43	        dims.extras   = find(data_size == header.rows);
44	    else % Data has a series stored
45	        dims.averages   = 0;
46	        dims.extras   = find(data_size == header.rows);
47	    end
48	else
