388	%%          %%% 5. DETERMINE POLARITY OF SPECTRUM (EG FOR MOIST WATER SUPP) %%%
389	            % Automate determination whether the Cr peak has positive polarity.
390	            % For water suppression methods like MOIST, the residual water may
391	            % actually have negative polarity, but end up positive in the data, so
392	            % that the spectrum needs to be flipped.
393	            if ~isfield(MRSCont.opts.SubSpecAlignment, 'polResidCr')
394	                if isfield(MRSCont.opts.SubSpecAlignment, 'PreservePolarity') && ~MRSCont.opts.SubSpecAlignment.PreservePolarity
395	                    raw_Cr     = op_freqrange(raw,2.8,3.2);
396	                    % Determine the polarity of the respective peak: if the absolute of the
397	                    % maximum minus the absolute of the minimum is positive, the polarity
398	                    % of the respective peak is positive; if the absolute of the maximum
399	                    % minus the absolute of the minimum is negative, the polarity is negative.
400	                    polResidCr = abs(max(real(raw_Cr.specs))) - abs(min(real(raw_Cr.specs)));
401	                    polResidCr = squeeze(polResidCr);
402	                    polResidCr(polResidCr<0) = -1;
403	                    polResidCr(polResidCr>0) = 1;
404	                else
405	                    polResidCr = 1;
406	                end
407	            else
408	                polResidCr = MRSCont.opts.SubSpecAlignment.polResidCr;
409	            end
410	            raw = op_ampScale(raw,polResidCr);
411	            MRSCont.raw{metab_ll,kk} = op_ampScale(MRSCont.raw{metab_ll,kk},polResidCr);
