1	% op_phaseCrCho.m
2	% Georg Oeltzschner, Johns Hopkins University 2019.
3	% 
4	% USAGE:
5	% [out,phaseShift]=op_phaseCrCho(in, suppressPlot);
6	% 
7	% DESCRIPTION:
8	% This function fits two Lorentzians to the Cr and Cho peaks, and optimizes
9	% the phase of the input spectrum based on Cr/Cho.
10	%
11	% If data with multiple averages is supplied, the fit is performed to the
12	% average, and all averages are phased accordingly.
13	% 
14	% INPUTS:
15	% in            = input data in matlab structure format. 
16	% suppressPlot  = (optional) Boolian to suppress plots.  Default = 0;
17	%
18	% OUTPUTS:
19	% out        = Output following automatic phasing.
20	% phShift    = The phase shift (in degrees) that was applied.
21	
22	function [out,phShift]=op_phaseCrCho(in, suppressPlot);
23	
24	if nargin < 2
25	    suppressPlot = 0;
26	end
27	
28	if in.dims.coils>0
29	    error('ERROR:  Can not operate on data with multilple coils!  ABORTING!!')
30	end
31	if in.dims.averages>0
32	    in_avg = op_averaging(in);
33	else
34	    in_avg = in;
35	end
36	if in.dims.extras>0
37	    error('ERROR:  Can not operate on data with extras dimension!  ABORTING!!');
38	end
39	if in.dims.subSpecs>0
40	    temp = cell(in.subspecs,1);
41	    phShift = zeros(in.subspecs,1);
42	    temp{1} = op_takesubspec(in_avg,1);
43	    % Fit the Cr-Cho doublet to the input spectrum
44	    parsFit = op_creChoFit(temp{1}, suppressPlot);
45	    % Extract phase adjustment
46	    phShift = ones(in.subspecs,1) * parsFit(4);
47	        % Apply negative phase of the fit to the data
48	    for ss = 1 : in.subspecs   
49	        temp{ss} = op_takesubspec(in_avg,ss);
50	        temp{ss}     = op_addphase(temp{ss}, -phShift(ss)*180/pi, 0, temp{ss}.centerFreq, suppressPlot);   
51	    end
52	    out = temp{1};
53	    for ss = 2 : in.subspecs
54	        out = op_mergesubspec(out,temp{ss});
55	    end
56	    
57	else
58	    % Fit the Cr-Cho doublet to the input spectrum
59	    parsFit = op_creChoFit(in_avg, suppressPlot);
60	    % Extract phase adjustment
61	    phShift = parsFit(4);
62	    % Apply negative phase of the fit to the data
63	    out     = op_addphase(in, -parsFit(4)*180/pi, 0, in.centerFreq, suppressPlot);
64	   
