classdef sb_map
%TEST-ONLY SHIM: minimal brace-indexable string-key map.
    properties
        keys = {};
        values = {};
    end
    methods
        function obj = sb_map()
        end

        function obj = subsasgn(obj, s, val)
            switch s(1).type
                case '{}'
                    k = s(1).subs{1};
                    idx = find(strcmp(obj.keys, k), 1);
                    if isempty(idx)
                        obj.keys{end+1} = k;
                        obj.values{end+1} = val;
                    else
                        obj.values{idx} = val;
                    end
                otherwise
                    obj = builtin('subsasgn', obj, s, val);
            end
        end

        function varargout = subsref(obj, s)
            switch s(1).type
                case '{}'
                    idx = find(strcmp(obj.keys, s(1).subs{1}), 1);
                    varargout{1} = obj.values{idx};
                otherwise
                    [varargout{1:nargout}] = builtin('subsref', obj, s);
            end
        end
    end
end

function failures = run_verification()
% End-to-end verification harness for the edited-MRS polarity repair.
%
% Runs the REAL reduced pipeline (io_loadspec_sdat -> osp_LoadSDAT ->
% OspreyProcess) on synthetic edited MRS datasets written in SDAT/SPAR
% format. Test-only shims (outputs/verify/shims) stand in for Osprey GUI /
% toolbox helpers that are absent from this reduced source tree; they never
% shadow functions that exist in source/.
%
% Asserts:
%   - default (corrected) workflow: subspectra become polarity-consistent
%     before combination (common reference retained in sum, suppressed in
%     difference, edited signal prominent in difference);
%   - SubSpecAlignment.PreservePolarity = true: original acquisition
%     polarity retained (distinct from corrected);
%   - SubSpecAlignment.polResidCr override is honored;
%   - healthy datasets (consistent polarity) are not altered;
%   - generality across sample counts, ppm grids, subspectrum counts.
%
% No public-fixture numbers are used anywhere; every expectation is derived
% from the generated data itself.

this_dir = fileparts(mfilename('fullpath'));
task_root = fileparts(fileparts(this_dir));
src = fullfile(task_root, 'source');

addpath(fullfile(this_dir, 'shims'));
addpath(fullfile(src, 'libraries', 'FID-A', 'inputOutput'));
addpath(fullfile(src, 'libraries', 'FID-A', 'processingTools'));
addpath(fullfile(src, 'process'));
addpath(fullfile(src, 'load'));
addpath(fullfile(src, 'settings'));

warning('off', 'all');
more off;

workroot = fullfile(this_dir, 'run');
if exist(workroot, 'dir')
    rmdir(workroot, 's');
end
mkdir(workroot);

failures = 0;

%% Case 1: MEGA edited, one acquisition condition 180 degrees out ----------
params = struct();
params.npts = 1560;
params.sw = 2500;
params.txfrq = 127731000;
params.navg = 3;
params.common_amps = [0.92, -0.83];   % second condition polarity-inverted
params.edited_amps = [0.28, 0.21];    % edited content keeps its sign
params.phases = [2, -6];
params.nsubspec = 2;
params.seed = 11;

[data_path] = write_sdat_case(workroot, 'mega_inverted', params);

% 1a: corrected workflow (default options: no PreservePolarity field)
MRSCont = fresh_mrscont(fullfile(workroot, 'out_mega_default'), 'MEGA');
MRSCont.files{1,1} = data_path;
MRSCont = osp_LoadSDAT(MRSCont);
MRSCont = OspreyProcess(MRSCont);
proc = MRSCont.processed.metab{1,1};
[consistency, retained_sum, suppression_diff, edited_ratio] = observe_mega(proc);
failures = failures + check('C1a default: common reference polarity-consistent', consistency > 0.99);
failures = failures + check('C1a default: sum retains common signal', retained_sum > 0.7);
failures = failures + check('C1a default: diff suppresses common signal', suppression_diff < 0.35);
failures = failures + check('C1a default: edited signal prominent in diff', edited_ratio > 1.5);

% 1b: intentional polarity-preserving workflow
MRSCont = fresh_mrscont(fullfile(workroot, 'out_mega_preserve'), 'MEGA');
MRSCont.files{1,1} = data_path;
MRSCont.opts.SubSpecAlignment.PreservePolarity = true;
MRSCont = osp_LoadSDAT(MRSCont);
MRSCont = OspreyProcess(MRSCont);
proc = MRSCont.processed.metab{1,1};
[consistency, retained_sum] = observe_mega(proc);
failures = failures + check('C1b preserve: original 180 deg relation kept', consistency < -0.99);
failures = failures + check('C1b preserve: common signal cancels in sum', retained_sum < 0.4);

% 1c: explicit manual polarity override
MRSCont = fresh_mrscont(fullfile(workroot, 'out_mega_override'), 'MEGA');
MRSCont.files{1,1} = data_path;
MRSCont.opts.SubSpecAlignment.polResidCr = [-1, 1];
MRSCont = osp_LoadSDAT(MRSCont);
MRSCont = OspreyProcess(MRSCont);
proc = MRSCont.processed.metab{1,1};
[consistency] = observe_mega(proc);
failures = failures + check('C1c override: vector honored (expects consistency +1)', consistency > 0.99);

%% Case 2: MEGA edited, healthy (already polarity-consistent) --------------
params.common_amps = [0.95, 0.81];
params.edited_amps = [0.24, 0.26];
params.npts = 1560;
params.seed = 23;
[data_path] = write_sdat_case(workroot, 'mega_healthy', params);
MRSCont = fresh_mrscont(fullfile(workroot, 'out_mega_healthy'), 'MEGA');
MRSCont.files{1,1} = data_path;
MRSCont = osp_LoadSDAT(MRSCont);
MRSCont_before = MRSCont.raw{1,1};
MRSCont = OspreyProcess(MRSCont);
proc = MRSCont.processed.metab{1,1};
[consistency, retained_sum, suppression_diff] = observe_mega(proc);
failures = failures + check('C2 healthy: stays consistent', consistency > 0.99);
failures = failures + check('C2 healthy: sum retains common signal', retained_sum > 0.7);
failures = failures + check('C2 healthy: diff suppresses common signal', suppression_diff > 0.5);

%% Case 3: HERMES-style 4 subspectra, two inverted conditions --------------
params = struct();
params.npts = 1320;
params.sw = 2100;
params.txfrq = 127731000;
params.navg = 2;
params.common_amps = [1.0, -0.87, -0.79, 0.93];
params.edited_amps = [0.22, 0.25, 0.21, 0.27];
params.phases = [1, -5, 3, -2];
params.nsubspec = 4;
params.seed = 37;
[data_path] = write_sdat_case(workroot, 'hermes_inverted', params);
MRSCont = fresh_mrscont(fullfile(workroot, 'out_hermes_default'), 'HERMES');
MRSCont.files{1,1} = data_path;
MRSCont = osp_LoadSDAT(MRSCont);
MRSCont = OspreyProcess(MRSCont);
proc = MRSCont.processed.metab{1,1};
[allpos, retained_sum] = observe_hermes(proc);
failures = failures + check('C3 hermes default: all subspectra polarity-consistent', allpos);
failures = failures + check('C3 hermes default: sum retains common signal', retained_sum > 0.7);

params2 = params;
MRSCont = fresh_mrscont(fullfile(workroot, 'out_hermes_preserve'), 'HERMES');
MRSCont.files{1,1} = data_path;
MRSCont.opts.SubSpecAlignment.PreservePolarity = true;
MRSCont = osp_LoadSDAT(MRSCont);
MRSCont = OspreyProcess(MRSCont);
proc = MRSCont.processed.metab{1,1};
[allpos, retained_sum] = observe_hermes(proc);
failures = failures + check('C3 hermes preserve: inverted conditions kept', ~allpos);
failures = failures + check('C3 hermes preserve: sum loses common signal', retained_sum < 0.5);

%% Case 4: unedited single spectrum with negative Cr polarity ---------------
params = struct();
params.npts = 1024;
params.sw = 1600;
params.txfrq = 127731000;
params.navg = 4;
params.common_amps = [-0.9];          % whole-acquisition inversion (MOIST-like)
params.edited_amps = [0.0];
params.phases = [1.5];
params.nsubspec = 1;
params.seed = 5;
[data_path] = write_sdat_case(workroot, 'unedited_neg', params);
MRSCont = fresh_mrscont(fullfile(workroot, 'out_unedited_default'), 'UnEdited');
MRSCont.files{1,1} = data_path;
MRSCont = osp_LoadSDAT(MRSCont);
MRSCont = OspreyProcess(MRSCont);
pol = observe_unedited(MRSCont.processed.metab{1,1});
failures = failures + check('C4 unedited default: Cr flipped positive', pol > 0);

MRSCont = fresh_mrscont(fullfile(workroot, 'out_unedited_preserve'), 'UnEdited');
MRSCont.files{1,1} = data_path;
MRSCont.opts.SubSpecAlignment.PreservePolarity = true;
MRSCont = osp_LoadSDAT(MRSCont);
MRSCont = OspreyProcess(MRSCont);
pol = observe_unedited(MRSCont.processed.metab{1,1});
failures = failures + check('C4 unedited preserve: original negative Cr kept', pol < 0);

fprintf('\n==== verification failures: %d ====\n', failures);
end

