% -------------------------------------------------------------------------
function data_path = write_sdat_case(workroot, casename, params)
% Writes a synthetic edited-MRS acquisition as SDAT/SPAR in the standard
% layout used by io_loadspec_sdat: rows hold (average, subspectrum) with
% subspectrum indices interleaved (odd/even splits as edited Philips data).
casedir = fullfile(workroot, casename);
mkdir(casedir);
data_path = fullfile(casedir, [casename '.sdat']);
spar_path = fullfile(casedir, [casename '.spar']);

npts = params.npts;
nsub = params.nsubspec;
navg = params.navg;
sw = params.sw;
txfrq = params.txfrq;

% Loader ppm axis (identical construction to io_loadspec_sdat).
Bo = txfrq / 42577000;
f = [(-sw/2)+(sw/(2*npts)):sw/(npts):(sw/2)-(sw/(2*npts))];
ppm = (f / (Bo * 42.577) + 4.68).';

cr_shape = exp(-0.5 .* ((ppm - 3.05) ./ 0.04) .^ 2);
cho_shape = 0.33 .* exp(-0.5 .* ((ppm - 3.19) ./ 0.045) .^ 2);
ed_shape = exp(-0.5 .* ((ppm - 2.31) ./ 0.055) .^ 2);

rand('seed', params.seed);
spectra = zeros(npts, nsub);
for ss = 1:nsub
    sig = params.common_amps(ss) .* (cr_shape + cho_shape) + params.edited_amps(ss) .* ed_shape;
    ph = params.phases(ss) * pi / 180;
    spec = real(sig .* exp(1i * ph));
    spec = spec + 1e-4 * randn(npts, 1);
    spectra(:, ss) = spec;
end

source_fids = ifft(ifftshift(spectra, 1), [], 1);
rows_in_file = nsub * navg;
fid_data = zeros(npts, rows_in_file);
for av = 1:navg
    for ss = 1:nsub
        row_index = (av - 1) * nsub + ss;
        fid_data(:, row_index) = source_fids(:, ss);
    end
end

packed = zeros(2, npts, rows_in_file);
packed(1, :, :) = real(fid_data);
packed(2, :, :) = imag(fid_data);

fid = fopen(data_path, 'w', 'ieee-le');
fwriteVAXG(fid, packed(:), 'float32');
fclose(fid);

fid = fopen(spar_path, 'w');
fprintf(fid, 'samples : %d\n', npts);
fprintf(fid, 'rows : %d\n', rows_in_file);
fprintf(fid, 'averages : %d\n', rows_in_file);
fprintf(fid, 'synthesizer_frequency : %d\n', txfrq);
fprintf(fid, 'sample_frequency : %d\n', sw);
fprintf(fid, 'echo_time : 62\n');
fprintf(fid, 'repetition_time : 2000\n');
if nsub == 2
    fprintf(fid, 'scan_id : MEGA\n');
else
    fprintf(fid, 'scan_id : HERMES\n');
end
fprintf(fid, 'scan_date : 2026.08.01\n');
fprintf(fid, 'ap_size : 20\n');
fprintf(fid, 'lr_size : 20\n');
fprintf(fid, 'cc_size : 20\n');
fprintf(fid, 'ap_off_center : 0\n');
fprintf(fid, 'lr_off_center : 0\n');
fprintf(fid, 'cc_off_center : 0\n');
fprintf(fid, 'ap_angulation : 0\n');
fprintf(fid, 'lr_angulation : 0\n');
fprintf(fid, 'cc_angulation : 0\n');
fprintf(fid, 'patient_position : HFS\n');
fprintf(fid, 'patient_orientation : TRA\n');
fclose(fid);
end

