function tf = contains(str, pat)
%TEST-ONLY SHIM for MATLAB contains() on char arrays and cellstr.
if iscellstr(str) || iscell(str)
    tf = false(size(str));
    for k = 1:numel(str)
        tf(k) = ~isempty(strfind(str{k}, pat));
    end
elseif ischar(str)
    tf = ~isempty(strfind(str, pat));
else
    tf = false;
end
end

